test('错误处理：BAD_JSON / METHOD_NOT_ALLOWED / 未知路径 404 / PAYLOAD_TOO_LARGE 413', async (t) => {
  const ctx = await bootstrap('kanban-api-errors-');
  teardown(t, ctx);

  const badJson = await fetch(`${ctx.url}/api/tasks`, { method: 'POST', headers: JSON_HEADERS, body: '{ 不是 json' });
  assert.equal(badJson.status, 400);
  assert.equal((await badJson.json()).error.code, 'BAD_JSON');

  const method = await fetch(`${ctx.url}/api/tasks`, { method: 'DELETE' });
  assert.equal(method.status, 405);
  assert.equal((await method.json()).error.code, 'METHOD_NOT_ALLOWED');

  const unknown = await fetch(`${ctx.url}/api/not-exist`);
  assert.equal(unknown.status, 404);
  assert.equal((await unknown.json()).error.code, 'NOT_FOUND');

  const big = JSON.stringify({ title: '大任务', pad: 'x'.repeat(1024 * 1024 + 64) });
  let status = null;
  let netError = null;
  try {
    const res = await fetch(`${ctx.url}/api/tasks`, { method: 'POST', headers: JSON_HEADERS, body: big });
    status = res.status;
    if (status === 413) {
      const body = await res.json();
      assert.equal(body.error.code, 'PAYLOAD_TOO_LARGE');
    }
  } catch (err) {
    netError = err;
  }
  assert.ok(
    status === 413,
    `超过 1MB 的请求体应返回 413 PAYLOAD_TOO_LARGE，实际 status=${status} netError=${netError && netError.message}`,
  );
});

